import { debounce } from "@ember/runloop";
import { service } from "@ember/service";
import AwsS3 from "@uppy/aws-s3";
import { Promise } from "rsvp";
import { ajax } from "discourse/lib/ajax";
import { isRateLimitError } from "discourse/lib/ajax-error";
import { withRateLimitRetry } from "discourse/lib/uploads";

const RETRY_DELAYS = [0, 1000, 3000, 5000];
const MB = 1024 * 1024;

const s3MultipartMeta = new WeakMap(); // file -> { attempts: { partNumber -> attempts }, signingErrorRaised: boolean, batchSigner: BatchSigner }

export default class UppyS3Multipart {
  @service siteSettings;

  constructor(owner, { uploadRootPath, errorHandler, uppyWrapper }) {
    setOwner(this, owner);
    this.uploadRootPath = uploadRootPath;
    this.uppyWrapper = uppyWrapper;
    this.errorHandler = errorHandler;
  }

  apply(uppyInstance) {
    this.uppyInstance = uppyInstance;

    this.uppyInstance.use(AwsS3, {
      // TODO: using multipart even for tiny files is not ideal. Now that uppy
      // made multipart a simple boolean, rather than a separate plugin, we can
      // consider combining our two S3 implementations and choose the strategy
      // based on file size.
      shouldUseMultipart: true,

      // Number of concurrent part uploads. AWS uses http/1.1,
      // which browsers limit to 6 concurrent connections per host.
      limit: 6,

      retryDelays: RETRY_DELAYS,

      // When we get to really big files, it's better to not have thousands
      // of small chunks, since we don't have a resume functionality if the
      // upload fails. Better to try upload less chunks even if those chunks
      // are bigger.
      getChunkSize(file) {
        if (file.size >= 500 * MB) {
          return 20 * MB;
        } else if (file.size >= 100 * MB) {
          return 10 * MB;
        } else {
          return 5 * MB;
        }
      },

      createMultipartUpload: this.#createMultipartUpload.bind(this),
      completeMultipartUpload: this.#completeMultipartUpload.bind(this),
      abortMultipartUpload: this.#abortMultipartUpload.bind(this),
      signPart: this.#signPart.bind(this),

      // we will need a listParts function at some point when we want to
      // resume multipart uploads; this is used by uppy to figure out
      // what parts are uploaded and which still need to be
    });
  }

  #createMultipartUpload(file) {
    this.uppyInstance.emit("create-multipart", file.id);

    const data = {
      file_name: file.name,
      file_size: file.size,
      upload_type: file.meta.upload_type,
      metadata: file.meta,
    };

    // the sha1 checksum is set by the UppyChecksum plugin, except
    // for in cases where the browser does not support the required
    // crypto mechanisms or an error occurs. it is an additional layer
    // of security, and not required.
    if (file.meta.sha1_checksum) {
      data.metadata = { "sha1-checksum": file.meta.sha1_checksum };
    }

    return withRateLimitRetry(() =>
      ajax(`${this.uploadRootPath}/create-multipart.json`, {
        type: "POST",
        data,
      })
    ).then((responseData) => {
      this.uppyInstance.emit("create-multipart-success", file.id);

      file.meta.unique_identifier = responseData.unique_identifier;
      return {
        uploadId: responseData.external_upload_identifier,
        key: responseData.key,
      };
    });
  }

  #getFileMeta(file) {
    if (s3MultipartMeta.has(file)) {
      return s3MultipartMeta.get(file);
    }

    const fileMeta = {
      attempts: {},
      signingErrorRaised: false,
      batchSigner: new BatchSigner({
        file,
        uploadRootPath: this.uploadRootPath,
      }),
    };

    s3MultipartMeta.set(file, fileMeta);
    return fileMeta;
  }

  async #signPart(file, partData) {
    const fileMeta = this.#getFileMeta(file);

    fileMeta.attempts[partData.partNumber] ??= 0;
    const thisPartAttempts = (fileMeta.attempts[partData.partNumber] += 1);

    this.uppyWrapper.debug.log(
      `[uppy] requesting signature for part ${partData.partNumber} (attempt ${thisPartAttempts})`
    );

    if (fileMeta.rateLimitError) {
      throw fileMeta.rateLimitError;
    }

    try {
      const url = await fileMeta.batchSigner.signedUrlFor(partData);
      this.uppyWrapper.debug.log(
        `[uppy] signature for part ${partData.partNumber} obtained, continuing.`
      );
      return { url };
    } catch (err) {
      // Uppy doesn't properly bubble errors from failed #signPart, so we call
      // the error handler ourselves after the last failed attempt
      if (isRateLimitError(err)) {
        fileMeta.rateLimitError = err;
      }

      if (
        !fileMeta.signingErrorRaised &&
        (fileMeta.rateLimitError || thisPartAttempts >= RETRY_DELAYS.length)
      ) {
        this.uppyWrapper.debug.log(
          `[uppy] Fetching a signed part URL for ${file.id} failed too many times, raising error.`
        );
        this.errorHandler(file, err);
        fileMeta.signingErrorRaised = true;
      }
      throw err;
    }
  }

  #completeMultipartUpload(file, data) {
    if (file.meta.cancelled) {
      return;
    }

    this.uppyInstance.emit("complete-multipart", file.id);
    const parts = data.parts.map((part) => {
      return { part_number: part.PartNumber, etag: part.ETag };
    });
    return withRateLimitRetry(() =>
      ajax(`${this.uploadRootPath}/complete-multipart.json`, {
        type: "POST",
        contentType: "application/json",
        data: JSON.stringify({
          parts,
          unique_identifier: file.meta.unique_identifier,
          pasted: file.meta.pasted,
          for_private_message: file.meta.for_private_message,
          for_site_setting: file.meta.for_site_setting,
          site_setting_name: file.meta.site_setting_name,
        }),
      })
    ).then((responseData) => {
      this.uppyInstance.emit("complete-multipart-success", file.id);
      return responseData;
    });
  }

  #abortMultipartUpload(file, { key, uploadId }) {
    // if the user cancels the upload before the key and uploadId
    // are stored from the createMultipartUpload response then they
    // will not be set, and we don't have to abort the upload because
    // it will not exist yet
    if (!key || !uploadId) {
      return;
    }

    // this gives us a chance to inspect the upload stub before
    // it is deleted from external storage by aborting the multipart
    // upload; see also ExternalUploadManager
    if (file.meta.error && this.siteSettings.enable_upload_debug_mode) {
      return;
    }

    file.meta.cancelled = true;

    return ajax(`${this.uploadRootPath}/abort-multipart.json`, {
      type: "POST",
      data: {
        external_upload_identifier: uploadId,
      },
    }).catch((err) => {
      this.errorHandler(file, err);
    });
  }
}

const BATCH_SIGNER_INITIAL_DEBOUNCE = 50;
const BATCH_SIGNER_REGULAR_DEBOUNCE = 500;

/**
 * This class is responsible for batching requests to the server to sign
 * parts of a multipart upload. It is used to avoid making a request for
 * every single part, which would likely hit our rate limits.
 */
class BatchSigner {
  pendingRequests = [];
  #madeFirstRequest = false;

  constructor({ file, uploadRootPath }) {
    this.file = file;
    this.uploadRootPath = uploadRootPath;
  }

  signedUrlFor(partData) {
    const promise = new Promise((resolve, reject) => {
      this.pendingRequests.push({
        partData,
        resolve,
        reject,
      });
    });

    this.#scheduleSigning();
    return promise;
  }

  #scheduleSigning() {
    debounce(
      this,
      this.#signParts,
      this.#madeFirstRequest
        ? BATCH_SIGNER_REGULAR_DEBOUNCE
        : BATCH_SIGNER_INITIAL_DEBOUNCE
    );
  }

  async #signParts() {
    if (this.pendingRequests.length === 0) {
      return;
    }

    this.#madeFirstRequest = true;

    const requests = this.pendingRequests;
    this.pendingRequests = [];

    try {
      const result = await withRateLimitRetry(() =>
        ajax(`${this.uploadRootPath}/batch-presign-multipart-parts.json`, {
          type: "POST",
          data: {
            part_numbers: requests.map(
              (request) => request.partData.partNumber
            ),
            unique_identifier: this.file.meta.unique_identifier,
          },
        })
      );
      requests.forEach(({ partData, resolve }) => {
        resolve(result.presigned_urls[partData.partNumber.toString()]);
      });
    } catch (err) {
      requests.forEach(({ reject }) => reject(err));
      return;
    }
  }
}
import { warn } from "@ember/debug";
import { setOwner } from "@ember/owner";
import { service } from "@ember/service";

export default class UppyUploadDebugging {
  @service siteSettings;

  constructor(owner) {
    setOwner(this, owner);
  }

  log(msg) {
    if (this.siteSettings.enable_upload_debug_mode) {
      // eslint-disable-next-line no-console
      console.log(msg);
    }
  }

  instrumentUploadTimings(uppy) {
    if (!this.#performanceApiSupport()) {
      warn(
        "Some browsers do not return a PerformanceMeasure when calling this.#performanceMark, disabling instrumentation. See https://developer.mozilla.org/en-US/docs/Web/API/Performance/measure#return_value and https://bugzilla.mozilla.org/show_bug.cgi?id=1724645",
        { id: "discourse.upload-debugging" }
      );
      return;
    }

    uppy.on("upload", (uploadID, files) => {
      files.forEach(({ id }) => this.#performanceMark(`upload-${id}-start`));
    });

    uppy.on("create-multipart", (fileId) => {
      this.#performanceMark(`upload-${fileId}-create-multipart`);
    });

    uppy.on("create-multipart-success", (fileId) => {
      this.#performanceMark(`upload-${fileId}-create-multipart-success`);
    });

    uppy.on("complete-multipart", (fileId) => {
      this.#performanceMark(`upload-${fileId}-complete-multipart`);

      this.#consolePerformanceTiming(
        this.#performanceMeasure(
          `upload-${fileId}-multipart-all-parts-complete`,
          `upload-${fileId}-create-multipart-success`,
          `upload-${fileId}-complete-multipart`
        )
      );
    });

    uppy.on("complete-multipart-success", (fileId) => {
      this.#performanceMark(`upload-${fileId}-complete-multipart-success`);

      this.#consolePerformanceTiming(
        this.#performanceMeasure(
          `upload-${fileId}-multipart-total-network-exclusive-complete-multipart`,
          `upload-${fileId}-create-multipart`,
          `upload-${fileId}-complete-multipart`
        )
      );

      this.#consolePerformanceTiming(
        this.#performanceMeasure(
          `upload-${fileId}-multipart-total-network-inclusive-complete-multipart`,
          `upload-${fileId}-create-multipart`,
          `upload-${fileId}-complete-multipart-success`
        )
      );

      this.#consolePerformanceTiming(
        this.#performanceMeasure(
          `upload-${fileId}-multipart-complete-convert-to-upload`,
          `upload-${fileId}-complete-multipart`,
          `upload-${fileId}-complete-multipart-success`
        )
      );
    });

    uppy.on("upload-success", (file) => {
      this.#performanceMark(`upload-${file.id}-end`);
      this.#consolePerformanceTiming(
        this.#performanceMeasure(
          `upload-${file.id}-multipart-total-inclusive-preprocessing`,
          `upload-${file.id}-start`,
          `upload-${file.id}-end`
        )
      );
    });
  }

  #consolePerformanceTiming(timing) {
    // Sometimes performance.measure can fail to return a PerformanceMeasure
    // object, in this case we can't log anything so return to prevent errors.
    if (!timing) {
      return;
    }

    const minutes = Math.floor(timing.duration / 60000);
    const seconds = ((timing.duration % 60000) / 1000).toFixed(0);
    const duration = minutes + ":" + (seconds < 10 ? "0" : "") + seconds;
    this.log(`${timing.name}:\n duration: ${duration} (${timing.duration}ms)`);
  }

  #performanceApiSupport() {
    this.#performanceMark("testing support 1");
    this.#performanceMark("testing support 2");
    const perfMeasure = this.#performanceMeasure(
      "performance api support",
      "testing support 1",
      "testing support 2"
    );
    return perfMeasure;
  }

  #performanceMark(markName) {
    return performance.mark(markName);
  }

  #performanceMeasure(measureName, startMark, endMark) {
    let measureResult;
    try {
      measureResult = performance.measure(measureName, startMark, endMark);
    } catch (error) {
      if (
        error.message.includes("Failed to execute 'measure' on 'Performance'")
      ) {
        // eslint-disable-next-line no-console
        console.warn(
          `Uppy performance measure failed: ${measureName}, ${startMark}, ${endMark}`
        );
      }
    }
    return measureResult;
  }
}
import { setOwner } from "@ember/owner";
import deprecated from "discourse/lib/deprecated";
import UppyUploadDebugging from "./upload-debugging.js";

/**
 * Use this class whenever you need to upload files or images
 * with Uppy. The class makes it easier to tell Uppy to use certain uppy plugins
 * as well as tracking all of the state of preprocessor plugins. For example,
 * you may have multiple preprocessors:
 *
 * - UppyMediaOptimization
 * - UppyChecksum
 *
 * Once installed with useUploadPlugin(PluginClass, opts), we track, for every
 * preprocessor plugin, the files that still need to be run through it. Files
 * are picked up from uppy's "upload" event; files removed from uppy
 * mid-preprocessing stop being waited on, and late events for them are ignored.
 *
 * If you need to do something else on progress or completion of preprocessors,
 * hook into the onPreProcessProgress(callback) or onPreProcessComplete(callback, allCompleteCallback)
 * functions. Note the onPreProcessComplete function takes a second callback
 * that is fired only when _all_ of the files have been preprocessed for all
 * preprocessor plugins.
 *
 * To completely reset the preprocessor state for all plugins, call resetPreProcessors.
 *
 * See ComposerUploadUppy for an example of a component using this class.
 */
export default class UppyWrapper {
  debug;
  uppyInstance;

  /** @type {Record<string, Set<string>>} pending file ids per preprocessor */
  #preProcessorStatus = {};
  #allCompleteCallbacks = [];
  #trackedInstance = null;

  constructor(owner) {
    setOwner(this, owner);
    this.debug = new UppyUploadDebugging(owner);
  }

  useUploadPlugin(pluginClass, opts = {}) {
    if (!this.uppyInstance) {
      return;
    }

    this.#trackUploads();

    if (!pluginClass.pluginId) {
      throw new Error(
        "The uppy plugin should have a static pluginId that is used to uniquely identify it."
      );
    }

    if (
      !pluginClass.pluginType ||
      !["preprocessor", "uploader"].includes(pluginClass.pluginType)
    ) {
      throw new Error(
        `The uppy plugin ${pluginClass.pluginId} should have a static pluginType that should be preprocessor or uploader`
      );
    }

    this.uppyInstance.use(
      pluginClass,
      Object.assign(opts, {
        id: pluginClass.pluginId,
        type: pluginClass.pluginType,
      })
    );

    if (pluginClass.pluginType === "preprocessor") {
      this.#preProcessorStatus[pluginClass.pluginId] = new Set();
    }
  }

  // NOTE: This and onPreProcessComplete will need to be tweaked
  // if we ever add support for "determinate" preprocessors for uppy, which
  // means the progress will have a value rather than a started/complete
  // state ("indeterminate").
  //
  // See: https://uppy.io/docs/writing-plugins/#Progress-events
  onPreProcessProgress(callback) {
    this.#trackUploads();
    this.uppyInstance.on("preprocess-progress", (file, progress, pluginId) => {
      if (!this.#isPending(pluginId, file)) {
        return;
      }

      this.debug.log(`[${pluginId}] processing file ${file.name} (${file.id})`);

      callback(file);
    });
  }

  onPreProcessComplete(callback, allCompleteCallback = null) {
    this.#trackUploads();
    if (allCompleteCallback) {
      this.#allCompleteCallbacks.push(allCompleteCallback);
    }

    this.uppyInstance.on("preprocess-complete", (file, skipped, pluginId) => {
      if (!this.#isPending(pluginId, file)) {
        return;
      }

      this.debug.log(
        `[${pluginId}] ${skipped ? "skipped" : "completed"} processing file ${
          file.name
        } (${file.id})`
      );

      callback(file);

      this.#preProcessorStatus[pluginId].delete(file.id);
      this.#notifyIfAllComplete();
    });
  }

  resetPreProcessors() {
    this.#eachPreProcessor((pluginId) => {
      this.#preProcessorStatus[pluginId] = new Set();
    });
  }

  addNeedProcessing() {
    deprecated(
      "`UppyWrapper#addNeedProcessing` is no longer needed; files are tracked from uppy's `upload` event.",
      { id: "discourse.uppy-wrapper-add-need-processing", since: "2026.10.0" }
    );
  }

  // The wrapper outlives its Uppy instance, which is rebuilt whenever the
  // editor is set up again, so tracking starts over for each instance.
  #trackUploads() {
    if (this.#trackedInstance === this.uppyInstance) {
      return;
    }
    this.#trackedInstance = this.uppyInstance;
    this.#preProcessorStatus = {};
    this.#allCompleteCallbacks = [];

    this.uppyInstance.on("upload", (uploadId, files) => {
      this.#eachPreProcessor((pluginId, pendingFileIds) => {
        files.forEach((file) => pendingFileIds.add(file.id));
      });
    });

    this.uppyInstance.on("file-removed", (file) => {
      let wasPending = false;
      this.#eachPreProcessor((pluginId, pendingFileIds) => {
        wasPending = pendingFileIds.delete(file.id) || wasPending;
      });

      // Removing the last file is a cancel-all, which consumers reset on themselves
      if (wasPending && this.uppyInstance.getFiles().length > 0) {
        this.#notifyIfAllComplete();
      }
    });
  }

  #eachPreProcessor(cb) {
    for (const [pluginId, pendingFileIds] of Object.entries(
      this.#preProcessorStatus
    )) {
      cb(pluginId, pendingFileIds);
    }
  }

  #isPending(pluginId, file) {
    return !!file && !!this.#preProcessorStatus[pluginId]?.has(file.id);
  }

  #notifyIfAllComplete() {
    const allComplete = Object.values(this.#preProcessorStatus).every(
      (pendingFileIds) => pendingFileIds.size === 0
    );

    if (allComplete) {
      this.debug.log("[uppy] All upload preprocessors complete!");
      this.#allCompleteCallbacks.forEach((callback) => callback());
    }
  }
}
import { warn } from "@ember/debug";
import { BasePlugin } from "@uppy/core";
import { Promise } from "rsvp";
import { isTesting } from "discourse/lib/environment";

export class UppyPluginBase extends BasePlugin {
  constructor(uppy, opts) {
    super(uppy, opts);
    this.id = this.constructor.pluginId;
  }

  _consoleWarn(msg) {
    if (!isTesting()) {
      warn(`[${this.id}] ${msg}`, { id: `discourse.${this.id}` });
    }
  }

  _getFile(fileId) {
    return this.uppy.getFile(fileId);
  }

  _setFileMeta(fileId, meta) {
    this.uppy.setFileMeta(fileId, meta);
  }

  _setFileState(fileId, state) {
    this.uppy.setFileState(fileId, state);
  }

  _emitAllComplete(fileIds, skipped = false) {
    fileIds.forEach((fileId) => {
      let file = this._getFile(fileId);
      this._emitComplete(file, skipped);
    });
    return Promise.resolve();
  }

  _emitError(file, errorMessage) {
    // the error message is stored twice; once to show in a displayErrorForUpload
    // modal, and on the .message property to show in the uppy logs
    this.uppy.emit("upload-error", file, {
      errors: [errorMessage],
      message: `[${this.id}] ${errorMessage}`,
    });
  }

  _skip(file) {
    return this._emitComplete(file, true);
  }

  _skipAll(file) {
    return this._emitAllComplete(file, true);
  }
}

export class UploadPreProcessorPlugin extends UppyPluginBase {
  static pluginType = "preprocessor";

  constructor(uppy, opts) {
    super(uppy, opts);
    this.type = this.constructor.pluginType;
  }

  _install(fn) {
    this.uppy.addPreProcessor(fn);
  }

  _uninstall(fn) {
    this.uppy.removePreProcessor(fn);
  }

  _emitProgress(file) {
    this.uppy.emit("preprocess-progress", file, null, this.id);
  }

  _emitComplete(file, skipped = false) {
    this.uppy.emit("preprocess-complete", file, skipped, this.id);
    return Promise.resolve();
  }
}

export class UploaderPlugin extends UppyPluginBase {
  static pluginType = "uploader";

